const supported=['kk','ru','en'];
let language=supported.includes(localStorage.getItem('language'))?localStorage.getItem('language'):'ru';
export const locale=()=>language==='kk'?'kk-KZ':language==='ru'?'ru-RU':'en-US';
export const getLanguage=()=>language;
export function t(key){const value=messages[key];return value?(language==='en'?(value[2]??key):value[language==='kk'?0:1]):key;}
export function languageSelect(){return `<label class="language-picker"><span>${t('Language')}</span><select data-language aria-label="${t('Language')}">${[['kk','Қазақша'],['ru','Русский'],['en','English']].map(([id,name])=>`<option value="${id}" ${id===language?'selected':''}>${name}</option>`).join('')}</select></label>`;}
export function setLanguage(value){if(!supported.includes(value))return;language=value;localStorage.setItem('language',value);document.documentElement.lang=value;localize();document.querySelectorAll('[data-language]').forEach(select=>select.value=value);window.dispatchEvent(new CustomEvent('languagechange'));}
const errorAliases={'Invalid email or password.':'invalidCredentials','This record already exists.':'accountExists','Reset link expired or used.':'resetExpired','Reset link already used.':'resetExpired','Invalid refresh token.':'sessionExpired','Refresh token expired.':'sessionExpired','Refresh token already used.':'sessionExpired','Unable to connect to the data service.':'serverUnavailable'};
export function errorText(data={},status=0){if(data.errors?.length)return [...new Set(data.errors.map(e=>t(messages[e.code]?e.code:'requestFailed')))].join(' ');const key=errorAliases[data.message]||data.code||data.message;if(key&&messages[key])return t(key);if(data.message&&!['Unable to complete the request.','Data service request failed.'].includes(data.message))return t(data.message);return t(status===429?'rateLimited':status===401?'sessionExpired':status===409?'accountExists':status>=500?'serverUnavailable':'requestFailed');}
