const reverse=new Map(Object.entries(messages).flatMap(([key,values])=>values.map(value=>[value,key])));
const sourceText=new WeakMap();
const translatedText=new WeakMap();
function translateText(value){const raw=value.trim(),key=messages[raw]?raw:reverse.get(raw)||raw;if(messages[key])return value.replace(raw,t(key));if(language==='en')return value;for(const [pattern,format] of patterns){const match=key.match(pattern);if(match)return value.replace(raw,format(match)[language==='kk'?0:1]);}if(raw.includes(' · '))return value.split(/(\s+·\s+)/).map(part=>part.trim()==='·'?part:translateText(part)).join('');return value;}
const sourceAttributes=new WeakMap();
export function localize(root=document.body){
 document.documentElement.lang=language;
 const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let node;
 while((node=walker.nextNode())){if(node.parentElement?.closest('script,style,textarea,code,[data-user-content],.language-picker option'))continue;if(!sourceText.has(node)||translatedText.get(node)!==node.nodeValue)sourceText.set(node,node.nodeValue);const value=translateText(sourceText.get(node));translatedText.set(node,value);if(value!==node.nodeValue)node.nodeValue=value;}
 root.querySelectorAll?.('[placeholder],[aria-label],[title]').forEach(el=>{if(el.closest('[data-user-content]'))return;let attributes=sourceAttributes.get(el);if(!attributes){attributes={};sourceAttributes.set(el,attributes);}for(const name of ['placeholder','aria-label','title'])if(el.hasAttribute(name)){const current=el.getAttribute(name);if(!attributes[name]||attributes[name].translated!==current)attributes[name]={source:current};const value=translateText(attributes[name].source);attributes[name].translated=value;if(value!==current)el.setAttribute(name,value);}});
}
export function observeTranslations(){const observer=new MutationObserver(()=>localize());observer.observe(document.body,{childList:true,subtree:true,characterData:true});document.addEventListener('change',e=>{if(e.target.matches('[data-language]'))setLanguage(e.target.value);});}
